    "/diagnostics": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        /**
         * Composite diagnostics dump (health + interfaces + incidents + log-levels)
         * @description Single ship-the-state artefact for support / agent escalation
         *     (ADR 0017). One JSON envelope carrying build info, health
         *     components + score, per-client detail, configured-interface
         *     list, recent incidents, system-status ring buffer, and
         *     log-level overrides.
         *
         *     **Two consumer planes — disjoint:**
         *
         *     - `GET /diagnostics` returns a momentary structured JSON
         *       snapshot. Right for support escalations, HA Repair-Flows,
         *       and any client that needs a coherent point-in-time view
         *       with one call.
         *     - `GET /metrics` returns Prometheus exposition format,
         *       right for time-series scraping (Grafana, Alertmanager).
         *       Continuous monitoring uses this; diagnostics-on-demand
         *       uses the JSON endpoint above.
         *
         *     The two surfaces are not interchangeable: the JSON envelope
         *     carries fields (recent incidents, log-overrides, system-status
         *     ring) that have no useful Prometheus representation; the
         *     Prometheus surface emits time-series that the JSON envelope
         *     does not aggregate.
         *
         *     Hashes device-address-shaped fields with a 12-hex sha256
         *     prefix by default; pass `?anonymize=0` explicitly when
         *     absolute fidelity is required.
         */
        get: operations["diagnosticsDump"];
        put?: never;
        post?: never;
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
